head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
scwin.vScrenID = "ULDBNS90003.xml";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vViewYn = '';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_Search
 * 설명       : 주권종목 데이터를 조회한다.
 ***********************************************/
scwin.fn_Search = function() {
    var param = '';
    param += "&{P}V_ISU_CD_NM=";
    param += "&{P}V_ISUR_CD=" + $c.stf.getObjectValue(txb_IsurCd);
    var dsNm = 'BNS_STKCERT_INFO';
    var qryId = 'lds.stf.bnscommon.select.listStkcertIsuCd';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_SetParam
 * 설명       : 부모창에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParam = function() {
    var prt = $c.frame.path("../");
    if (prt != undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar != undefined) {
        var arrPar = new Array();
        scwin.fn_GetPar(arrPar);
        $c.stf.setObjectValue(txb_IsurCd, arrPar[0].ISUR_CD);
        if (arrPar[0].POP_CALL_YN != 'undefined') {
            scwin.vViewYn = arrPar[0].POP_CALL_YN;
        } else if (arrPar[0].DELETE_YN != 'undefined') {
            scwin.vViewYn = arrPar[0].DELETE_YN;
        }
    }
};




/********************************************** 
 * 함수명   : fn_SetParStkcertIsu
 * 설명       : 부모창에 보낼 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParStkcertIsu = async function(delYn) {
    var arrPar = new Array();
    arrPar[0] = {
        STD_CD: dts_List.getCellData(dts_List.getRowPosition(), "STD_CD"),
        ISU_NM: dts_List.getCellData(dts_List.getRowPosition(), "ISU_NM"),
        ISUR_CD: dts_List.getCellData(dts_List.getRowPosition(), "ISUR_CD"),
        DELETE_YN: delYn
    };
    scwin.fn_SetPar(arrPar);
    await $c.frame.CloseFrame();
};
scwin.dts_List_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    txb_TotalCnt.setValue("총 " + rowcount + "건");
};
scwin.grd_List_OnDblClick = function(row, colid) {
    if (scwin.vViewYn == 'Y') return;
    scwin.fn_SetParStkcertIsu('N');
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.bns.BnsPanelToGroupBox(panel_1);
    //파라미터설정
    scwin.fn_SetParam();
    if ($c.stf.getObjectValue(txb_IsurCd) != '') scwin.fn_Search();
};
scwin.txb_IsurCd_onkeypress = function() {
    if (window.event.keyCode == 13) scwin.fn_Search();
};
